/// <summary> Конструктор класса </summary>
public void new()
{
    apiClient = new RMarketApiClientBinance();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::GET);
    apiClient.parmMethodUrl('/api/v3/exchangeInfo');

    // Do this before execute()
    //apiClient.setBaseUrl('');
}

/// <summary>
/// Устанавливает основные параметры запроса
/// </summary>
/// <param name="_symbol">Торговая пара</param>
public void initParameters(RMarketSymbolId _symbol, RMarketType _marketType)
{
    symbol = strUpr(_symbol);

    apiClient.addQueryParam('symbol', symbol);
}

public void prepare()
{
    // Add your code here...

    super();
}

public void processResponse()
{
    super();

    str responseStr = apiClient.getResponseBody();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
        throw Error(strfmt("Request returns error!"));

    responseContract = RMarketJsonSerializer::deserializeObject(
        classNum(RMarketJson_Binance_ExchangeInfo),
        responseStr) as RMarketJson_Binance_ExchangeInfo;
}

container getInfoCon()
{
    RMarketJson_Binance_ExchangeInfo_Filter filter, pricefilter, limitFilter, marketFilter, notionFilter;
    List ls = responseContract.parmSymbols();
    ListEnumerator enum = ls.getEnumerator();
    enum.moveNext();
    RMarketJson_Binance_ExchangeInfo_Symbol item = enum.current();

    ls = item.parmFilters();
    enum = ls.getEnumerator();
    while (enum.moveNext())
    {
        filter = enum.current();
        switch (filter.parmFilterType())
        {
            case 'PRICE_FILTER':    pricefilter  = filter; break;
            case 'LOT_SIZE':        limitFilter  = filter; break;
            case 'MARKET_LOT_SIZE': marketFilter = filter; break;
            //case 'TRAILING_DELTA':
            //case 'PERCENT_PRICE_BY_SIDE':
            case 'NOTIONAL':        notionFilter = filter; break;
            //case 'MAX_NUM_ORDERS':
            //case 'MAX_NUM_ALGO_ORDERS':
        }
    }

    container ret = [//item.parmBaseAsset(), item.parmQuoteAsset()];
        power(0.1, item.parmBaseAssetPrecision()),  //BasePrecision
        power(0.1, item.parmQuoteAssetPrecision()), //QuotePrecision
        str2Num(pricefilter.parmMinPrice()),        //MinPrice
        str2Num(pricefilter.parmMaxPrice()),        //MaxPrice
        str2Num(pricefilter.parmTickSize()),        //StepPrice
        str2Num(marketFilter.parmMinQty()),         //MinMarketQty
        str2Num(marketFilter.parmMaxQty()),         //MaxMarketQty
        str2Num(marketFilter.parmStepSize()),       //StepMarketQty
        str2Num(limitFilter.parmMinQty()),          //MinLimitQty
        str2Num(limitFilter.parmMaxQty()),          //MaxLimitQty
        str2Num(limitFilter.parmStepSize()),        //StepLimitQty
        str2Num(notionFilter.parmMinNotional()),    //MinLimitAmount
        str2Num(notionFilter.parmMaxNotional()),    //MaxLimitAmount
        (notionFilter.parmApplyMinToMarket() == true) ? str2Num(notionFilter.parmMinNotional()) : 0,   //MinMarketAmount
        (notionFilter.parmApplyMaxToMarket() == true) ? str2Num(notionFilter.parmMaxNotional()) : 0    //MaxMarketAmount
        ];
    return ret;
}
